namespace Scada.Api.Runtime;

public static partial class ContextualHelpCatalog
{
    private static ContextualHelpSection LS(string locale, string ph, string eh, string sh, string pb, string eb, string sb, string? code = null) =>
        new(Pick(locale, ph, eh, sh), Pick(locale, pb, eb, sb), code);

    private static ContextualHelpTopic LT(string locale, string id, string category, LocalizedText title, LocalizedText summary, ContextualHelpSection[] sections, params string[] related) =>
        new(id, category, title.For(locale), summary.For(locale), sections, related);

    private static ContextualHelpTopic ExpandLearningLinks(ContextualHelpTopic topic)
    {
        string[] more = topic.Id switch
        {
            "home-building.device-workflow" => ["drivers.radio-connections", "drivers.zigbee-native-setup", "drivers.zigbee2mqtt-setup", "drivers.zwave-setup"],
            "drivers.overview" => ["sources.connection-workflow", "drivers.siemens-setup", "drivers.logix-setup", "drivers.melsec-setup", "drivers.panasonic-setup", "drivers.dnp3-setup", "drivers.iec104-setup", "drivers.modbus-server-setup", "drivers.radio-connections", "drivers.matter-test-workflow"],
            "driver.dnp3.master" => ["drivers.dnp3-setup", "sources.connection-workflow"],
            "driver.iec60870.5.104" => ["drivers.iec104-setup", "sources.connection-workflow"],
            "driver.modbus.tcp.server" or "driver.modbus.rtu.server" => ["drivers.modbus-server-setup", "gateway.configure-test"],
            "driver.siemens.s7.iso" => ["drivers.siemens-setup", "sources.connection-workflow"],
            "driver.rockwell.logix.eip" => ["drivers.logix-setup", "sources.connection-workflow"],
            "driver.mitsubishi.melsec.mc" => ["drivers.melsec-setup", "sources.connection-workflow"],
            "driver.panasonic.mewtocol.tcp" or "driver.panasonic.mewtocol.serial" => ["drivers.panasonic-setup", "sources.connection-workflow"],
            "driver.zigbee.native" => ["drivers.zigbee-native-setup", "drivers.radio-connections"],
            "driver.zigbee2mqtt.bridge" => ["drivers.zigbee2mqtt-setup", "drivers.radio-connections"],
            "driver.zwave.js.controller" => ["drivers.zwave-setup", "drivers.radio-connections"],
            "home-building.organization" => ["home-building.device-workflow", "drivers.homeassistant-setup", "drivers.esphome-setup", "drivers.shelly-setup"],
            "driver.bacnet.ip" => ["drivers.bacnet-setup", "sources.connection-workflow"],
            "driver.knx.ip" => ["drivers.knx-setup", "sources.connection-workflow"],
            "driver.homeassistant.websocket" => ["drivers.homeassistant-setup", "home-building.device-workflow"],
            "driver.esphome.native" => ["drivers.esphome-setup", "home-building.device-workflow"],
            "driver.shelly.rpc" => ["drivers.shelly-setup", "home-building.device-workflow"],
            "sources.data-sources" => ["sources.connection-workflow", "drivers.modbus-setup", "drivers.mqtt-setup", "drivers.opcua-setup"],
            "driver.modbus.tcp" or "driver.modbus.rtu" => ["drivers.modbus-setup", "sources.connection-workflow"],
            "driver.mqtt.raw" => ["drivers.mqtt-setup", "sources.connection-workflow"],
            "driver.opc-ua" => ["drivers.opcua-setup", "sources.connection-workflow"],
            "libraries.reusable-resources" => ["libraries.associate-incorporate", "assets.management"],
            "gateway.overview" => ["gateway.configure-test", "engineering.tabular-workflow"],
            "screens.overview" or "popups.overview" or "visual.properties" => ["visual.first-screen", "visual.object-selection", "visual.popup-workflow", "visual.object.core.numericinput", "visual.object.core.trend"],
            "scripts.engineering" or "scripts.python-validation" => ["scripts.choose-scope", "scripts.server-syntax", "scripts.triggers-dependencies", "scripts.server-recipes", "scripts.client-recipes"],
            "scripts.server" => ["scripts.server-syntax", "scripts.triggers-dependencies", "scripts.server-recipes", "scripts.commands-feedback"],
            "scripts.client-visual" => ["scripts.choose-scope", "scripts.client-api", "scripts.client-recipes", "visual.events"],
            "intelligence.overview" => ["equipment.overview", "intelligence.activation", "intelligence.profiles-equipment", "intelligence.semantics", "intelligence.operating-contexts", "intelligence.analysis-guide", "intelligence.dashboard-workflow"],
            "engineering.shell-navigation" or "help.find-your-way" => ["getting-started.first-project", "help.application-map", "templates.overview", "equipment.overview", "database.topology", "ha.overview"],
            "getting-started.neutral-bootstrap" => ["getting-started.first-project", "recovery.backup-system-recovery"],
            "installation.switching" => ["installation.switch-workflow", "recovery.backup-system-recovery"],
            "dynamos.overview" or "libraries.reusable-resources" => ["templates.overview", "equipment.overview"],
            "ha.overview" => ["ha.configuration-operation", "database.topology"],
            "reports.overview" => ["reports.data-designer", "reports.layout-variables", "reports.runtime-output", "historian.capture-query"],
            "historian.overview" or "tags.overview" => ["historian.capture-query", "reports.data-designer"],
            "runtime.history" => ["historian.capture-query", "reports.runtime-output"],
            "visual.object.core.trend" or "trends.overview" => ["visual.trend-series"],
            "visual.object.core.alarmbrowser" or "visual.object.core.eventbrowser" => ["visual.browser-filters"],
            _ => []
        };
        return topic with { RelatedTopicIds = (topic.RelatedTopicIds ?? []).Concat(more).Where(id => id != topic.Id).Distinct(StringComparer.Ordinal).ToArray() };
    }

    private static IEnumerable<ContextualHelpTopic> BuildLearningGuides(string locale)
    {
        yield return LT(locale, "engineering.overview", "engineering",
            Tx("Engenharia: caminho para montar uma aplicação", "Engineering: a path to build an application", "Ingeniería: recorrido para preparar una aplicación"),
            Tx("Organize o trabalho desde as primeiras conexões até a revisão que o operador usa.", "Organize work from initial connections to the revision an operator uses.", "Organice el trabajo desde las conexiones iniciales hasta la revisión del operador."),
            [
                LS(locale, "Construa uma parte de cada vez", "Build one part at a time", "Prepare una parte cada vez",
                    "Comece com um equipamento e uma leitura que você consiga conferir. Configure sua fonte de dados e o TAG, apresente o valor em uma tela e confirme a unidade. Depois acrescente estados, comandos, alarmes e histórico conforme a necessidade. Assim você sabe em qual camada procurar quando um valor ou ação não funciona.",
                    "Begin with one Equipment and a reading you can verify. Configure its Data Source and TAG, show the value on a screen and check its unit. Then add states, commands, alarms and history as needed. This makes it clear which layer to investigate when a value or action fails.",
                    "Empiece con un equipo y una lectura comprobable. Configure fuente y TAG, muestre el valor y compruebe la unidad. Añada después estados, comandos, alarmas e histórico. Así sabrá qué capa revisar cuando no funcione un valor o acción."),
                LS(locale, "Siga o caminho dos dados", "Follow the data path", "Siga el recorrido del dato",
                    "Fonte de dados define como conectar. TAG identifica o ponto e seu tipo/endereço. Tela/Popup apresenta o ponto e recebe interações. Histórico guarda amostras quando a captura foi configurada. Script aplica uma regra com recursos declarados. Security Authority decide quem pode executar cada ação; a licença e a classe da sessão podem restringir o recurso. Não use um botão visível como prova de que uma escrita está autorizada.",
                    "A Data Source defines the connection. A TAG identifies a point and its type/address. Screen/Popup presents it and receives interactions. History stores samples when capture is configured. A Script applies a rule using declared resources. Security Authority decides who can perform each action; licensing and session class can further restrict it. A visible button is not proof that writing is authorized.",
                    "La Fuente define conexión. TAG identifica punto y tipo/dirección. Pantalla/Popup lo presenta y recibe interacciones. Histórico guarda muestras si hay captura configurada. Script aplica reglas con recursos declarados. Security Authority decide quién ejecuta acciones; licencia y clase pueden restringir más. Un botón visible no prueba autorización de escritura."),
                LS(locale, "Prepare a revisão para operação", "Prepare the operating revision", "Prepare la revisión para operación",
                    "1. Confira projeto e Working antes de editar. 2. Valide cada recurso e resolva referências ausentes. 3. Use a Pré-visualização e aplique o rascunho quando esse fluxo estiver presente. 4. Salve o trabalho e revise as mudanças. 5. Publique e ative a revisão pelo ciclo de vida do projeto. 6. No Runtime, confirme a revisão ativa e confira a tarefa que o operador realmente fará. Salvar uma edição não muda automaticamente o que já está operando.",
                    "1. Check project and Working before editing. 2. Validate resources and resolve missing references. 3. Preview and apply a draft where that flow exists. 4. Save and review changes. 5. Publish and activate through project lifecycle. 6. In Runtime, confirm the active revision and verify the operator's actual task. Saving an edit does not automatically change what is already running.",
                    "1. Compruebe proyecto y Working. 2. Valide recursos y referencias. 3. Use Vista previa y aplique borradores cuando corresponda. 4. Guarde y revise cambios. 5. Publique y active mediante el ciclo del proyecto. 6. Confirme la revisión activa en Runtime y la tarea del operador. Guardar una edición no cambia automáticamente lo que está operando.")
            ], "engineering.lifecycle", "sources.data-sources", "tags.overview", "visual.first-screen", "scripts.choose-scope", "troubleshooting.overview");

        yield return LT(locale, "troubleshooting.overview", "troubleshooting",
            Tx("Encontrar a causa de um problema", "Find the cause of a problem", "Encontrar la causa de un problema"),
            Tx("Parta do sintoma e confira uma camada por vez, preservando o contexto do que falhou.", "Start from the symptom and check one layer at a time while preserving the failure's context.", "Parta del síntoma y compruebe una capa cada vez conservando el contexto del fallo."),
            [
                LS(locale, "Guarde a informação antes de repetir", "Keep the information before retrying", "Conserve información antes de repetir",
                    "Anote a tarefa, recurso, horário e mensagem apresentada. Confira instalação, projeto e revisão ativa. Uma nova tentativa sem mudar a causa pode repetir uma escrita ou um comando. Em resultado ambíguo de comando, confira primeiro o feedback do equipamento. Não apague dados, recrie contas ou importe outro projeto como tentativa genérica de correção.",
                    "Record task, resource, time and displayed message. Check installation, project and active revision. A retry without addressing the cause can repeat a write or command. For an ambiguous command outcome, check Equipment feedback first. Do not delete data, recreate accounts or import another project as a generic fix.",
                    "Anote tarea, recurso, hora y mensaje. Compruebe instalación, proyecto y revisión activa. Reintentar sin corregir causa puede repetir una escritura o comando. Ante resultado ambiguo, compruebe primero feedback del equipo. No borre datos, recree cuentas ni importe otro proyecto como arreglo genérico."),
                new ContextualHelpSection(Pick(locale, "Procure pelo sintoma", "Look up the symptom", "Busque el síntoma"), Pick(locale,
                    "Faça as verificações na ordem indicada e abra o guia da área para detalhar cada campo. Se precisar de suporte, inclua os resultados dessas verificações e evite compartilhar credenciais.",
                    "Follow checks in order and open the area's guide for field details. For support, include check results and avoid sharing credentials.",
                    "Siga las comprobaciones en orden y abra la guía del área para detalles. Para soporte incluya resultados y no comparta credenciales."), Fields:
                [
                    IF(locale, "missing-value", "Valor vazio ou desatualizado", "Missing or stale value", "Valor ausente o desactualizado", "Confira status da Fonte de dados, endereço e tipo do TAG; depois qualidade e timestamp. Por último, revise o vínculo da tela. Não substitua ausência por zero.", "Check Data Source status, TAG address/type, then quality and timestamp. Finally check screen binding. Do not replace absence with zero.", "Compruebe Fuente, dirección/tipo TAG, calidad y timestamp. Después el vínculo de pantalla. No sustituya ausencia por cero.", "Compare o TAG fora da tela", "Inspect the TAG outside the screen", "Inspeccione el TAG fuera de la pantalla"),
                    IF(locale, "saved-not-live", "Salvou, mas o Runtime não mudou", "Saved, but Runtime did not change", "Guardó, pero Runtime no cambió", "Confira se o rascunho foi aplicado, se a revisão foi salva/publicada e qual revisão está ativa. Compare o recurso na revisão correta antes de editar de novo.", "Check draft application, saved/published revision and which revision is active. Compare the resource in the correct revision before editing again.", "Compruebe aplicación del borrador, revisión guardada/publicada y revisión activa. Compare antes de volver a editar.", "Abra o ciclo de vida do projeto", "Open project lifecycle", "Abra ciclo del proyecto"),
                    IF(locale, "invisible-object", "Objeto não aparece", "Object is invisible", "Objeto no aparece", "Confira seleção na Estrutura, visibilidade, opacidade, tamanho, posição e sobreposição. Depois confira dinâmicas que alteram essas propriedades.", "Check Structure selection, visibility, opacity, size, position and stacking. Then check dynamics affecting those properties.", "Compruebe Estructura, visibilidad, opacidad, tamaño, posición y superposición; después dinámicas asociadas.", "Selecione na Estrutura", "Select in Structure", "Seleccione en Estructura"),
                    IF(locale, "action-failed", "Botão ou escrita sem efeito", "Button or write has no effect", "Botón o escritura sin efecto", "Confira evento/destino e estado habilitado; depois classe da sessão e permissão. Leia o retorno do comando e o feedback físico antes de repetir.", "Check event/target and enabled state, then session class and permission. Read command outcome and physical feedback before retrying.", "Compruebe evento/destino y habilitación, clase y permiso. Lea resultado y feedback físico antes de repetir.", "Diferencie pedido enviado de concluído", "Distinguish sent from completed", "Distinga enviado de concluido"),
                    IF(locale, "script-not-running", "Script não executa", "Script does not run", "Script no se ejecuta", "Confira escopo, handler exato, evento e dependências. Leia o primeiro diagnóstico e confirme a revisão ativa. Um erro de referência não se resolve apenas mudando a sintaxe.", "Check scope, exact handler, event and dependencies. Read the first diagnostic and confirm active revision. A reference error is not fixed by syntax changes alone.", "Compruebe alcance, handler, evento y dependencias. Lea primer diagnóstico y revisión activa. Un error de referencia no se arregla solo con sintaxis.", "Abra o guia de ligação de eventos", "Open the event-connection guide", "Abra la guía de conexión de eventos"),
                    IF(locale, "history-empty", "Histórico vazio", "Empty history", "Histórico vacío", "Confira captura habilitada no TAG, período e fuso horário; depois qualidade e filtros. Configurar captura agora não cria amostras do passado.", "Check TAG capture, period and timezone, then quality and filters. Enabling capture now does not create past samples.", "Compruebe captura TAG, período y zona; después calidad y filtros. Habilitar captura no crea muestras pasadas.", "Comece com um período curto conhecido", "Start with a known short period", "Empiece con un período corto conocido"),
                    IF(locale, "intelligence-empty", "Inteligência bloqueada ou sem resultado", "Intelligence blocked or without results", "Inteligencia bloqueada o sin resultado", "Confira licença, permissão explícita e escopo ativado; depois associação/perfil, sinais exigidos e evidência histórica/contextual. Dados insuficientes não provam normalidade ou defeito.", "Check license, explicit permission and activated scope, then assignment/profile, required signals and historical/context evidence. Insufficiency proves neither health nor fault.", "Compruebe licencia, permiso y alcance activo; después perfil, señales y evidencia histórica/contextual. Insuficiencia no prueba normalidad ni fallo.", "Leia a razão de insuficiência", "Read the insufficiency reason", "Lea la razón de insuficiencia")
                ])
            ], "diagnostics.overview", "tags.quality", "engineering.lifecycle", "scripts.triggers-dependencies", "intelligence.overview");

        yield return LT(locale, "help.find-your-way", "getting-started",
            Tx("Encontre a orientação certa", "Find the guidance you need", "Encuentre la orientación adecuada"),
            Tx("Escolha uma tarefa e siga um exemplo pequeno antes de ampliar sua aplicação.", "Choose a task and follow a small example before expanding your application.", "Elija una tarea y siga un ejemplo pequeño antes de ampliar su aplicación."),
            [
                LS(locale, "Por onde começar", "Where to start", "Por dónde empezar",
                    "Se você está conhecendo o SCADIVO, comece pelo primeiro acesso e ciclo de vida do projeto. Depois conecte uma fonte, crie um TAG e apresente esse TAG em uma tela. Esse caminho permite entender de onde o valor vem antes de configurar alarmes, histórico ou cálculos.",
                    "If you are new to SCADIVO, begin with first access and the project lifecycle. Then connect a source, create a TAG and show that TAG on a screen. This path helps you understand where the value comes from before configuring alarms, history or calculations.",
                    "Si está conociendo SCADIVO, empiece por el primer acceso y ciclo del proyecto. Después conecte una fuente, cree un TAG y muéstrelo en una pantalla. Así comprenderá de dónde viene el valor antes de configurar alarmas, histórico o cálculos."),
                LS(locale, "Use as áreas e a busca", "Use areas and search", "Use áreas y búsqueda",
                    "Abra uma área na lista ao lado para ver seus guias. Em Telas, popups e objetos, os objetos são separados em formas, mídia, controles e medidores. Se já está preenchendo um campo, procure seu nome; se escreve um Script, procure a função. A busca considera também as explicações dos campos e os exemplos de código. O índice Neste artigo leva diretamente à seção necessária.",
                    "Open an area in the side list to see its guides. Screens, popups and objects separates shapes, media, controls and gauges. If you are filling a field, search its name; if writing a Script, search its function. Search also includes field explanations and code examples. In this article links directly to the section you need.",
                    "Abra un área de la lista lateral para ver sus guías. Pantallas, popups y objetos separa formas, multimedia, controles y medidores. Si está completando un campo, busque su nombre; si escribe un Script, busque la función. La búsqueda incluye explicaciones y código. En este artículo enlaza directamente a cada sección."),
                LS(locale, "Como aproveitar os exemplos", "How to use examples", "Cómo aprovechar ejemplos",
                    "Os nomes de TAG e equipamento nos exemplos são demonstrativos. Crie seus recursos e use o seletor de referências para inserir os correspondentes do seu projeto. Leia primeiro os pré-requisitos e o resultado esperado; copiar o código sem configurar dependências ou eventos não completa a tarefa. Faça a primeira tentativa em uma aplicação de teste.",
                    "TAG and Equipment names in examples are illustrative. Create your resources and use the reference picker to insert their counterparts from your project. Read prerequisites and expected behavior first; copying code without configuring dependencies or events does not complete the task. Make your first attempt in a test application.",
                    "Los nombres de TAG y equipo son demostrativos. Cree sus recursos y use el selector para insertar los de su proyecto. Lea requisitos y resultado esperado; copiar código sin configurar dependencias o eventos no completa la tarea. Haga el primer intento en una aplicación de prueba.")
            ], "getting-started.startup-authentication", "engineering.lifecycle", "sources.data-sources", "tags.overview", "visual.first-screen", "scripts.choose-scope");

        yield return LT(locale, "visual.first-screen", "visual",
            Tx("Sua primeira tela: do TAG ao valor visível", "Your first screen: from TAG to visible value", "Su primera pantalla: del TAG al valor visible"),
            Tx("Monte uma tela pequena com título, leitura e indicação de estado para entender o editor.", "Build a small screen with a title, reading and state indicator to learn the editor.", "Prepare una pantalla pequeña con título, lectura e indicador de estado para conocer el editor."),
            [
                LS(locale, "Prepare um exemplo que você consiga conferir", "Prepare an example you can check", "Prepare un ejemplo comprobable",
                    "Neste exercício, você vai mostrar uma pressão numa tela. Use um TAG numérico existente, cuja leitura e unidade você conheça, e abra o projeto de teste em Engenharia. TAG é a variável que guarda essa leitura. Se ainda não possui uma variável de teste, siga Primeiro projeto para preparar uma sem equipamento.\n\nA Tela ocupa a área principal do Runtime. Um Popup é uma janela de apoio, aberta a partir dela. Comece pela Tela; depois acrescente o Popup se precisar de detalhes. Criar a Tela não a inclui automaticamente na navegação.",
                    "In this exercise, you will show pressure on a screen. Use an existing numeric TAG with a known reading and unit, and open the test project in Engineering. A TAG is the variable holding that reading. If you do not yet have a test variable, follow First project to prepare one without equipment.\n\nA Screen occupies the main Runtime area. A Popup is a supporting window opened from it. Start with the Screen, then add a Popup if details are needed. Creating a Screen does not automatically add it to navigation.",
                    "En este ejercicio mostrará una presión en pantalla. Use un TAG numérico existente cuya lectura y unidad conozca y abra el proyecto de prueba en Ingeniería. Un TAG es la variable que contiene esa lectura. Si aún no tiene una variable de prueba, siga Primer proyecto para preparar una sin equipo.\n\nLa Pantalla ocupa el área principal del Runtime. Un Popup es una ventana de apoyo abierta desde ella. Empiece por la Pantalla y añada un Popup si necesita detalles. Crear la Pantalla no la incorpora automáticamente a la navegación."),
                new ContextualHelpSection(Pick(locale, "Veja como os objetos se combinam", "See how objects fit together", "Vea cómo se combinan los objetos"), Pick(locale,
                    "Na captura real abaixo, rótulos e leituras aparecem na parte superior, o desenho do processo fica à esquerda e a tendência à direita. Cada parte atende uma tarefa e tem configuração própria. Os botões de detalhes abrem informações de cada bomba; uma imagem do equipamento, sozinha, não define seu comportamento.",
                    "In this real capture, labels and readings appear at the top, the process drawing is on the left and the trend on the right. Each part serves a task and has its own configuration. Detail buttons open information for each pump; an equipment image alone does not define its behavior.",
                    "En esta captura real, etiquetas y lecturas están arriba, el dibujo del proceso a la izquierda y la tendencia a la derecha. Cada parte cumple una tarea y tiene configuración propia. Los botones de detalles abren información de cada bomba; una imagen sola no define su comportamiento."), Figure: new ContextualHelpFigure(
                        "/help/eee-runtime-screen.jpg",
                        Pick(locale, "Tela real da demonstração EEE com leituras, bombas, botões e tendência.", "Real EEE demonstration screen with readings, pumps, buttons and a trend.", "Pantalla real de demostración EEE con lecturas, bombas, botones y tendencia."),
                        Pick(locale, "Demonstração EEE, captura de 22/10/2026 em português. Dados simulados; exemplo de composição personalizável, não disposição obrigatória do produto.", "EEE demonstration captured on 22 October 2026 in Portuguese. Simulated data; an example of a customizable composition, not a mandatory product layout.", "Demostración EEE capturada el 22/10/2026 en portugués. Datos simulados; ejemplo de composición personalizable, no disposición obligatoria del producto."))),
                LS(locale, "Crie, organize e vincule", "Create, arrange and bind", "Crear, organizar y vincular",
                    "1. Crie uma Tela e escolha dimensões para o dispositivo que usará.\n2. Adicione um Texto com o nome do equipamento. Esse título fica fixo e não precisa de TAG.\n3. Adicione uma Exibição de valor. Selecione-a no desenho; se estiver difícil encontrá-la, use a Estrutura, a lista de objetos da tela.\n4. No Inspetor, o painel de propriedades do objeto, ajuste posição, tamanho, formato e casas decimais.\n5. No vínculo de dados, escolha o TAG pelo seletor. Esse vínculo faz o objeto acompanhar a variável; não digite um ID por tentativa.\n6. Coloque a unidade próxima do valor e confira se corresponde à leitura.\n7. Depois que a leitura funcionar, acrescente outras indicações. Para mudar uma cor conforme um estado, primeiro defina qual condição a cor deve representar.",
                    "1. Create a Screen and choose dimensions for the device you will use.\n2. Add Text with the equipment name. This title is fixed and needs no TAG.\n3. Add a Value Display. Select it in the drawing; if it is hard to find, use Structure, the screen’s object list.\n4. In the Inspector, the object’s property panel, adjust position, size, format and decimal places.\n5. In the data binding, choose the TAG through the picker. This connection makes the object follow the variable; do not guess an ID.\n6. Place the unit near the value and check that it matches the reading.\n7. Once the reading works, add other indications. Before changing a color with a state, define which condition the color represents.",
                    "1. Cree una Pantalla y elija dimensiones para el dispositivo de uso.\n2. Añada Texto con el nombre del equipo. Ese título es fijo y no necesita TAG.\n3. Añada un Valor mostrado. Selecciónelo en el dibujo; si cuesta encontrarlo, use Estructura, la lista de objetos de la pantalla.\n4. En el Inspector, el panel de propiedades del objeto, ajuste posición, tamaño, formato y decimales.\n5. En el vínculo de datos, elija el TAG con el selector. Ese vínculo hace que el objeto siga la variable; no adivine un ID.\n6. Coloque la unidad junto al valor y compruebe que corresponde a la lectura.\n7. Cuando funcione la lectura, añada otras indicaciones. Antes de cambiar un color según un estado, defina qué condición representa."),
                LS(locale, "Entenda as três formas de mudar a aparência", "Understand three ways to change appearance", "Entienda tres formas de cambiar el aspecto",
                    "Um valor fixo define o desenho inicial, como fundo azul. Um vínculo ou Dinâmica acompanha uma origem, como nível ou estado da bomba. Um evento reage a uma interação, como Click. Não são etapas obrigatórias para todo objeto: um título costuma ser fixo, uma leitura usa vínculo e um botão pode usar evento. Quando houver Script, use a chave da propriedade documentada no tópico do objeto.",
                    "A fixed value defines the initial drawing, such as a blue background. A binding or Dynamic follows a source, such as level or pump state. An event responds to interaction, such as Click. Not every object needs all three: a title is usually fixed, a reading uses a binding and a button may use an event. For a Script, use the property key documented in the object's topic.",
                    "Un valor fijo define el dibujo inicial, como fondo azul. Un vínculo o Dinámica sigue un origen, como nivel o estado de bomba. Un evento responde a interacción, como Click. No todo objeto necesita los tres: un título suele ser fijo, una lectura usa vínculo y un botón puede usar evento. En Scripts, use la clave documentada en el tema del objeto."),
                LS(locale, "Confira antes de operar", "Check before operating", "Comprobar antes de operar",
                    "Comece pela Pré-visualização: ela permite conferir a alteração e ler os diagnósticos antes de Aplicar. Aplicar leva a edição ao rascunho do projeto, chamado Working. Salvar cria uma revisão; Publicar a prepara para uso; Ativar a coloca em execução. Use os controles do projeto e confira cada confirmação.\n\nNo Runtime, compare a leitura com uma fonte independente. Confira também o que aparece sem dados: indisponibilidade não deve parecer uma pressão real igual a zero. Mudar o desenho no editor não atualiza, por si só, a revisão em execução.",
                    "Start with Preview: check the edit and read diagnostics before Apply. Apply puts the edit in the project draft, called Working. Save creates a revision; Publish prepares it for use; Activate puts it into execution. Use the project controls and check each confirmation.\n\nIn Runtime, compare the reading with an independent source. Also check what appears without data: unavailability must not look like a real zero pressure. Editing the drawing alone does not update the running revision.",
                    "Empiece por Vista previa: compruebe la edición y lea los diagnósticos antes de Aplicar. Aplicar lleva la edición al borrador del proyecto, llamado Working. Guardar crea una revisión; Publicar la prepara para uso; Activar la pone en ejecución. Use los controles del proyecto y compruebe cada confirmación.\n\nEn Runtime, compare la lectura con una fuente independiente. Compruebe también qué aparece sin datos: la indisponibilidad no debe parecer una presión real de cero. Editar el dibujo no actualiza por sí solo la revisión en ejecución.")
            ], "getting-started.first-project", "visual.object-selection", "visual.object.core.valuedisplay", "visual.properties", "visual.dynamics", "engineering.lifecycle");

        yield return LT(locale, "visual.object-selection", "visual",
            Tx("Qual objeto usar em cada situação", "Which object to use", "Qué objeto usar en cada situación"),
            Tx("Escolha pela função que o operador precisa executar, depois ajuste a aparência.", "Choose according to the operator's task, then adjust appearance.", "Elija según la tarea del operador y después ajuste el aspecto."),
            [
                LS(locale, "Informar, representar ou agir", "Inform, represent or act", "Informar, representar o actuar",
                    "Para mostrar uma leitura, escolha Exibição de valor ou um Medidor; para comparar evolução no tempo, Tendência. Formas e Texto compõem o desenho, mas precisam de vínculos para representar estados variáveis. Botão, Entrada numérica e Controle deslizante recebem interação: antes de habilitá-los, defina destino, permissão e feedback. Um desenho de bomba não se torna um comando de partida apenas por ter aparência de botão.",
                    "Use Value display or a Gauge for a reading and Trend for changes over time. Shapes and Text build the drawing but need bindings to represent changing states. Button, Numeric input and Slider receive interaction: define target, permission and feedback before enabling them. A pump drawing does not become a start command just because it looks clickable.",
                    "Use Visualización de valor o Medidor para una lectura y Tendencia para cambios temporales. Formas y Texto componen el dibujo, pero necesitan vínculos para estados variables. Botón, Entrada numérica y Deslizante reciben interacción: defina destino, permiso y realimentación antes de habilitarlos. Un dibujo de bomba no se convierte en comando de arranque por parecer pulsable."),
                LS(locale, "Objetos parecidos têm propriedades diferentes", "Similar objects have different properties", "Objetos parecidos tienen propiedades distintas",
                    "Um Texto configura letras e alinhamento; uma Imagem configura recurso e enquadramento; um Medidor acrescenta escala e qualidade; uma Tendência acrescenta séries e tempo; uma Entrada numérica acrescenta limites e confirmação. Abra o subtópico do tipo escolhido para consultar todos os campos suportados e seus exemplos. Os medidores por faixas e com alvo têm referências visuais específicas, que não configuram alarmes ou setpoints.",
                    "Text configures lettering and alignment; Image configures an asset and framing; Gauge adds scale and quality; Trend adds series and time; Numeric input adds limits and confirmation. Open the selected type's subtopic for its supported fields and examples. Band and Target gauges have special visual references that do not configure alarms or setpoints.",
                    "Texto configura letras y alineación; Imagen configura recurso y encuadre; Medidor añade escala y calidad; Tendencia añade series y tiempo; Entrada numérica añade límites y confirmación. Abra el subtema del tipo para consultar campos y ejemplos. Los medidores por bandas y con objetivo usan referencias visuales que no configuran alarmas ni consignas."),
                LS(locale, "Reutilize um conjunto pronto", "Reuse a prepared assembly", "Reutilizar un conjunto preparado",
                    "Use um Dínamo quando o mesmo conjunto visual se repete para vários equipamentos. Configure sua interface pública por instância, como TAGs e comandos; editar a definição compartilhada pode afetar todas as instâncias ligadas. Um Grupo apenas organiza objetos, enquanto um Dínamo também representa uma definição reutilizável.",
                    "Use a Dynamo when the same visual assembly repeats across Equipment. Configure public parameters per instance, such as TAGs and commands; editing the shared definition can affect every linked instance. A Group organizes objects, whereas a Dynamo also represents a reusable definition.",
                    "Use un Dínamo cuando el mismo conjunto se repite para varios equipos. Configure parámetros públicos por instancia, como TAGs y comandos; editar la definición compartida puede afectar todas las instancias vinculadas. Un Grupo organiza objetos; un Dínamo representa además una definición reutilizable.")
            ], "visual.object.core.rectangle", "visual.object.core.text", "visual.object.core.image", "visual.object.core.valuedisplay", "visual.object.core.numericinput", "visual.object.core.trend", "dynamos.overview");

        yield return LT(locale, "visual.popup-workflow", "popups",
            Tx("Popup: preparar detalhes e configurar a abertura", "Popup: prepare details and configure opening", "Popup: preparar detalles y configurar apertura"),
            Tx("Use uma janela de apoio para detalhes de um equipamento sem perder o contexto da tela principal.", "Use a supporting window for Equipment details without losing the main screen's context.", "Use una ventana de apoyo para detalles de equipo sin perder el contexto principal."),
            [
                LS(locale, "Planeje conteúdo e tamanho", "Plan content and size", "Planificar contenido y tamaño",
                    "Um Popup permite ver detalhes sem trocar a tela principal. Por exemplo, Detalhes da bomba pode reunir nome, pressão e estado. Crie-o na área Popups com um nome que explique essa finalidade e dimensões que caibam no dispositivo.\n\nMonte primeiro as leituras; acrescente ações quando os destinos e permissões estiverem definidos. Os objetos usam os mesmos tipos de propriedade das Telas. O Popup precisa de uma ação na tela de origem para ser aberto; apenas criá-lo não o exibe ao operador.",
                    "A Popup shows details without replacing the main screen. For example, Pump details can bring together its name, pressure and state. Create it in Popups with a name explaining that purpose and dimensions that fit the device.\n\nBuild the readings first; add actions once targets and permissions are defined. Objects use the same property types as Screens. A Popup needs an action on the source screen to open it; creating it alone does not display it to the operator.",
                    "Un Popup muestra detalles sin cambiar la pantalla principal. Por ejemplo, Detalles de la bomba puede reunir nombre, presión y estado. Créelo en Popups con un nombre que explique esa finalidad y dimensiones adecuadas al dispositivo.\n\nMonte primero las lecturas; añada acciones cuando estén definidos destinos y permisos. Los objetos usan los mismos tipos de propiedad que las Pantallas. Un Popup necesita una acción en la pantalla de origen para abrirse; crearlo no lo muestra al operador."),
                LS(locale, "Configure e confira a abertura", "Configure and check opening", "Configurar y comprobar apertura",
                    "1. Monte os objetos do Popup e escolha os TAGs reais das leituras.\n2. Execute a Pré-visualização, confira os avisos e aplique a edição ao projeto.\n3. Volte à tela de origem e selecione o objeto que abrirá a janela, como um botão Detalhes.\n4. Configure a ação de abrir Popup disponível no editor e selecione o Popup criado. Se a definição pedir parâmetros ou referências, preencha-os para o equipamento correto.\n5. Salve a revisão, publique e ative usando os controles do projeto. O Runtime usa a versão ativada, não apenas o rascunho do editor.\n6. No Runtime, use o botão configurado. Confira nome do equipamento, leituras e tamanho da janela. Feche-a e confirme o retorno à tela principal.",
                    "1. Build the Popup objects and choose the real reading TAGs.\n2. Run Preview, check the messages and apply the edit to the project.\n3. Return to the source screen and select the object that will open the window, such as a Details button.\n4. Configure the editor’s available open-Popup action and select the Popup you created. If its definition asks for parameters or references, fill them for the correct equipment.\n5. Save the revision, publish and activate through the project controls. Runtime uses the activated version, not just the editor draft.\n6. In Runtime, use the configured button. Check equipment name, readings and window size. Close it and confirm return to the main screen.",
                    "1. Monte los objetos del Popup y elija los TAGs reales de lectura.\n2. Ejecute Vista previa, compruebe los mensajes y aplique la edición al proyecto.\n3. Vuelva a la pantalla de origen y seleccione el objeto que abre la ventana, como un botón Detalles.\n4. Configure la acción disponible para abrir Popup y seleccione el creado. Si la definición pide parámetros o referencias, complételos para el equipo correcto.\n5. Guarde la revisión, publique y active con los controles del proyecto. Runtime usa la versión activada, no solo el borrador del editor.\n6. En Runtime, use el botón configurado. Compruebe nombre del equipo, lecturas y tamaño. Cierre la ventana y confirme la vuelta a la pantalla principal."),
                LS(locale, "Se a janela não aparecer", "If the window does not appear", "Si la ventana no aparece",
                    "Confirme que o Popup e a ação estão na revisão ativa e que o destino selecionado ainda existe. Se abrir com dados de outro equipamento, revise as referências da instância; não tente corrigir mudando apenas o título. Se houver Script no evento, confira se o handler realmente executou. Abrir uma janela não concede permissão para comandos dentro dela.",
                    "Check that the Popup and action are in the active revision and that the selected target still exists. If it shows another Equipment's data, review instance references; changing its title does not fix that. If the event uses a Script, check that its handler actually ran. Opening a window does not grant permission for its commands.",
                    "Compruebe que Popup y acción estén en la revisión activa y que el destino exista. Si muestra datos de otro equipo, revise referencias de instancia; cambiar el título no lo corrige. Si usa Script, compruebe que el handler se ejecutó. Abrir una ventana no concede permiso para sus comandos.")
            ], "popups.overview", "visual.first-screen", "visual.events", "bindings-commands.overview");

        foreach (var topic in BuildScriptLearningGuides(locale)) yield return topic;
        foreach (var topic in BuildIntelligenceLearningGuides(locale)) yield return topic;
        foreach (var topic in BuildObjectWorkflowGuides(locale)) yield return topic;
    }
}
